import sys
from collections import deque

class BTreeNode:
    def __init__(self, leaf=False):
        self.keys = []
        self.children = []
        self.leaf = leaf

class BTree:
    def __init__(self, t):
        self.root = None
        self.t = t

    def insert(self, k):
        if self.root is None:
            self.root = BTreeNode(True)
            self.root.keys.append(k)
        else:
            if len(self.root.keys) == 2 * self.t - 1:
                temp = BTreeNode(False)
                temp.children.append(self.root)
                self.root = temp
                self._split_child(temp, 0)
            self._insert_non_full(self.root, k)

    def _split_child(self, parent, i):
        t = self.t
        full_node = parent.children[i]
        new_node = BTreeNode(full_node.leaf)
        mid_key = full_node.keys[t - 1]

        new_node.keys = full_node.keys[t:]
        full_node.keys = full_node.keys[:t - 1]

        if not full_node.leaf:
            new_node.children = full_node.children[t:]
            full_node.children = full_node.children[:t]

        parent.keys.insert(i, mid_key)
        parent.children.insert(i + 1, new_node)

    def _insert_non_full(self, node, k):
        i = len(node.keys) - 1
        if node.leaf:
            node.keys.append(0)
            while i >= 0 and k < node.keys[i]:
                node.keys[i + 1] = node.keys[i]
                i -= 1
            node.keys[i + 1] = k
        else:
            while i >= 0 and k < node.keys[i]:
