            self._delete(node.children[idx], k)

    def _get_pred(self, node, idx):
        curr = node.children[idx]
        while not curr.leaf:
            curr = curr.children[-1]
        return curr.keys[-1]

    def _get_succ(self, node, idx):
        curr = node.children[idx + 1]
