        next_child = node.children[idx + 1]
        child.keys.append(node.keys[idx])
        child.keys.extend(next_child.keys)
        if not child.leaf:
            child.children.extend(next_child.children)
        child.leaf = True
        node.keys.pop(idx)
        node.children.pop(idx + 1)

